export function translate(text: string, lang: Lang, vars?: Record<string, string | number>) {
  const message = lang !== 'en' && Object.hasOwn(dict, text) ? dict[text][lang] : text
  return vars
    ? message.replace(/\{(\w+)\}/g, (match, key) => Object.hasOwn(vars, key) ? String(vars[key]) : match)
    : message
}

